sp_widget.client_script:
function ($scope, $sce) {
	var c = this;
	c.html = $sce.trustAsHtml(c.options.html);
	$scope.$watch('c.options.html',function(){
		c.html = $sce.trustAsHtml(c.options.html);
	})
}

sp_widget.css:
.campusdesk-actions {
  max-width: 1100px;
  margin: 0 auto;
  padding: 55px 30px 65px;
  font-family: Arial, sans-serif;
}

.campusdesk-actions-header {
  text-align: center;
  margin-bottom: 35px;
}

.campusdesk-actions-label {
  display: inline-block;
  padding: 7px 14px;
  border: 1px solid #d7e8d0;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: #5c8f35;
}

.campusdesk-actions-header h2 {
  margin: 14px 0 8px;
  font-size: 30px;
  font-weight: 700;
  color: #123247;
}

.campusdesk-actions-header p {
  margin: 0;
  font-size: 15px;
  color: #667781;
}

.campusdesk-action-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.campusdesk-action-card {
  display: flex;
  align-items: center;
  position: relative;
  min-height: 125px;
  padding: 25px;
  background: #ffffff;
  border: 1px solid #e1e8eb;
  border-radius: 14px;
  text-decoration: none;
  box-shadow: 0 4px 14px rgba(10, 40, 55, 0.06);
  transition: all 0.2s ease;
}

.campusdesk-action-card:hover {
  transform: translateY(-3px);
  border-color: #8bd14f;
  box-shadow: 0 8px 22px rgba(10, 40, 55, 0.11);
}

.campusdesk-action-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin-right: 20px;
  background: #eef8e7;
  border-radius: 14px;
  font-size: 27px;
  flex-shrink: 0;
}

.campusdesk-action-content {
  padding-right: 35px;
}

.campusdesk-action-content h3 {
  margin: 0 0 7px;
  color: #123247;
  font-size: 18px;
  font-weight: 700;
}

.campusdesk-action-content p {
  margin: 0;
  color: #71808a;
  font-size: 13px;
  line-height: 1.5;
}

.campusdesk-action-arrow {
  position: absolute;
  right: 22px;
  color: #7ac943;
  font-size: 22px;
  font-weight: 700;
}

@media (max-width: 700px) {

  .campusdesk-actions {
    padding: 40px 18px;
  }

  .campusdesk-action-grid {
    grid-template-columns: 1fr;
  }

  .campusdesk-actions-header h2 {
    font-size: 25px;
  }

}
